import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load font at module level to guarantee availability before frame 0
const { fontFamily: interFamily } = loadInter();



export type MortalityRiskChartProps = Record<string, any>;

const MortalityRiskChart: React.FC<MortalityRiskChartProps> = ({
  backgroundColor = "#0a0c10",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "5–6× Higher Mortality Risk for Low Scorers",
  subtitle = "Adults scoring 0–4 (Low SRT) vs 8–10 (High SRT) on Mortality Risk",
  highScoreColor = "#3b82f6", // Blue for healthy/low risk
  lowScoreColor = "#ef4444", // Red for danger/high risk
  textColor = "#ffffff",
  gridLineColor = "rgba(255, 255, 255, 0.1)",
  chartData = [
    {
      label: "Natural Causes",
      highScoreValue: 1,
      lowScoreValue: 5.5,
    },
    {
      label: "Cardiovascular Death",
      highScoreValue: 1,
      lowScoreValue: 6,
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive dimensions
  const chartWidth = width * 0.8;
  const chartHeight = height * 0.55;
  const paddingX = width * 0.1;
  const paddingY = height * 0.15;

  // Calculate max value for chart scale
  const maxValue = Math.max(
    ...chartData.map((d) => Math.max(d.lowScoreValue, d.highScoreValue, 1)),
    6 // Ensure at least 6 for the scale context
  );

  // Animations - Text/Titles
  const titleOpacity = interpolate(frame, [5, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  const subtitleOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateRight: "clamp",
  });
  const subtitleY = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Animations - Chart Area
  const gridOpacity = interpolate(frame, [15, 30], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const legendOpacity = interpolate(frame, [20, 35], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
      }}
    >
      {/* Header Container */}
      <div
        style={{
          position: "absolute",
          top: paddingY,
          left: paddingX,
          width: chartWidth,
          display: "flex",
          flexDirection: "column",
          gap: "1rem",
        }}
      >
        <h1
          style={{
            fontSize: "3.5rem",
            fontWeight: 800,
            margin: 0,
            lineHeight: 1.1,
            opacity: titleOpacity,
            transform: `translateY(${interpolate(titleY, [0, 1], [30, 0])}px)`,
            transition: "none",
          }}
        >
          {title}
        </h1>
        <p
          style={{
            fontSize: "1.75rem",
            color: `${textColor}b3`, // 70% opacity
            margin: 0,
            opacity: subtitleOpacity,
            transform: `translateY(${interpolate(subtitleY, [0, 1], [20, 0])}px)`,
            maxWidth: "75%",
            transition: "none",
          }}
        >
          {subtitle}
        </p>
      </div>

      {/* Legend */}
      <div
        style={{
          position: "absolute",
          top: height * 0.05,
          right: paddingX,
          display: "flex",
          gap: "2rem",
          opacity: legendOpacity,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          <div
            style={{
              width: 24,
              height: 24,
              backgroundColor: highScoreColor,
              borderRadius: 4,
            }}
          />
          <span style={{ fontSize: "1.25rem", fontWeight: 500 }}>
            High Score (8-10)
          </span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          <div
            style={{
              width: 24,
              height: 24,
              backgroundColor: lowScoreColor,
              borderRadius: 4,
            }}
          />
          <span style={{ fontSize: "1.25rem", fontWeight: 500 }}>
            Low Score (0-4)
          </span>
        </div>
      </div>

      {/* Chart Container */}
      <div
        style={{
          position: "absolute",
          bottom: paddingY,
          left: paddingX,
          width: chartWidth,
          height: chartHeight,
          opacity: gridOpacity,
          transition: "none",
        }}
      >
        {/* Background Grid Lines (Y-Axis) */}
        {[0, 1, 2, 3, 4, 5, 6].map((step, i) => {
          const yPos = chartHeight - (step / 6) * chartHeight;
          return (
            <div
              key={`grid-${i}`}
              style={{
                position: "absolute",
                top: yPos,
                left: 0,
                width: "100%",
                height: 2,
                backgroundColor: gridLineColor,
                display: "flex",
                alignItems: "center",
              }}
            >
              <span
                style={{
                  position: "absolute",
                  left: -60,
                  fontSize: "1.25rem",
                  color: `${textColor}80`, // 50% opacity
                  fontWeight: 500,
                }}
              >
                {step}x
              </span>
            </div>
          );
        })}

        {/* Chart Bars (Flex Row for Data) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            justifyContent: "space-around",
            alignItems: "flex-end",
            paddingBottom: 2, // Offset for bottom border
            boxSizing: "border-box",
          }}
        >
          {chartData.map((data, index) => {
            const groupDelay = 25 + index * 15;
            
            // Springs for bar heights
            const highBarSpring = spring({
              frame: frame - groupDelay,
              fps,
              config: { damping: 15, stiffness: 90, mass: 1.2 },
            });
            
            const lowBarSpring = spring({
              frame: frame - groupDelay - 10, // slightly delayed after high score
              fps,
              config: { damping: 15, stiffness: 90, mass: 1.2 },
            });

            // Height calculations
            const highH = (data.highScoreValue / maxValue) * chartHeight;
            const lowH = (data.lowScoreValue / maxValue) * chartHeight;

            // Interpolated text values for counting effect
            const currentHighVal = interpolate(highBarSpring, [0, 1], [0, data.highScoreValue]);
            const currentLowVal = interpolate(lowBarSpring, [0, 1], [0, data.lowScoreValue]);

            // Formatter logic: show decimal only if necessary and non-zero
            const formatValue = (v: number) => {
              if (v === 0) return "";
              return (v % 1 === 0 ? v.toFixed(0) : v.toFixed(1)) + "x";
            };

            return (
              <div
                key={data.label}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  width: "30%",
                  height: "100%",
                  justifyContent: "flex-end",
                  position: "relative",
                  transition: "none",
                }}
              >
                {/* Bar Group */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "flex-end",
                    justifyContent: "center",
                    gap: "1.5rem",
                    width: "100%",
                    height: "100%",
                  }}
                >
                  {/* High Score Bar */}
                  <div
                    style={{
                      width: "30%",
                      height: highH,
                      backgroundColor: highScoreColor,
                      transformOrigin: "bottom center",
                      transform: `scaleY(${highBarSpring})`,
                      borderTopLeftRadius: 8,
                      borderTopRightRadius: 8,
                      position: "relative",
                      transition: "none",
                      boxShadow: `0 0 20px ${highScoreColor}33`,
                    }}
                  >
                    <span
                      style={{
                        position: "absolute",
                        top: -40,
                        left: 0,
                        width: "100%",
                        textAlign: "center",
                        fontSize: "1.5rem",
                        fontWeight: 700,
                        color: highScoreColor,
                        opacity: highBarSpring > 0.1 ? 1 : 0,
                      }}
                    >
                      {formatValue(currentHighVal)}
                    </span>
                  </div>

                  {/* Low Score Bar */}
                  <div
                    style={{
                      width: "30%",
                      height: lowH,
                      backgroundColor: lowScoreColor,
                      transformOrigin: "bottom center",
                      transform: `scaleY(${lowBarSpring})`,
                      borderTopLeftRadius: 8,
                      borderTopRightRadius: 8,
                      position: "relative",
                      transition: "none",
                      boxShadow: `0 0 20px ${lowScoreColor}33`,
                    }}
                  >
                    <span
                      style={{
                        position: "absolute",
                        top: -40,
                        left: 0,
                        width: "100%",
                        textAlign: "center",
                        fontSize: "1.5rem",
                        fontWeight: 700,
                        color: lowScoreColor,
                        opacity: lowBarSpring > 0.1 ? 1 : 0,
                      }}
                    >
                      {formatValue(currentLowVal)}
                    </span>
                  </div>
                </div>

                {/* X-Axis Label */}
                <span
                  style={{
                    position: "absolute",
                    bottom: -50,
                    fontSize: "1.5rem",
                    fontWeight: 600,
                    textAlign: "center",
                    width: "100%",
                    opacity: interpolate(frame, [groupDelay + 10, groupDelay + 25], [0, 1], {
                      extrapolateRight: "clamp",
                    }),
                    transform: `translateY(${interpolate(
                      spring({ frame: frame - groupDelay - 10, fps, config: { damping: 12 } }),
                      [0, 1],
                      [10, 0]
                    )}px)`,
                    transition: "none",
                  }}
                >
                  {data.label}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MortalityRiskChart;